solution.Sorts.java:
import java.util.*;

class Sorts {
    static void insertionSort(int[] a) {
        for (int i = 1; i < a.length; i++) {
            int key = a[i], j = i - 1;
            while (j >= 0 && a[j] > key) {
                a[j + 1] = a[j];
                j--;
            }
            a[j + 1] = key;
        }
    }

    static int[] mergeSort(int[] a) {
        int[] copy = a.clone();
        countAndSort(copy, new int[copy.length], 0, copy.length);
        return copy;
    }

    static long countInversions(int[] a) {
        int[] copy = a.clone();
        return countAndSort(copy, new int[copy.length], 0, copy.length);
    }

    private static long countAndSort(int[] a, int[] tmp, int from, int to) {
        if (to - from < 2) return 0;
        int mid = (from + to) >>> 1;
        long count = countAndSort(a, tmp, from, mid) + countAndSort(a, tmp, mid, to);
        int i = from, j = mid, k = from;
        while (i < mid && j < to) {
            if (a[i] <= a[j]) tmp[k++] = a[i++];
            else {
                count += mid - i;          // a[j] is smaller than every remaining left item
                tmp[k++] = a[j++];
            }
        }
        while (i < mid) tmp[k++] = a[i++];
        while (j < to) tmp[k++] = a[j++];
        System.arraycopy(tmp, from, a, from, to - from);
        return count;
    }

    static <T> void stableSort(List<T> list, Comparator<? super T> cmp) {
        if (list.size() < 2) return;
        int half = list.size() / 2;
        List<T> left = new ArrayList<>(), right = new ArrayList<>();
        for (int i = 0; i < half; i++) left.add(list.get(i));
        for (int i = half; i < list.size(); i++) right.add(list.get(i));
        stableSort(left, cmp);
        stableSort(right, cmp);
        int i = 0, j = 0, k = 0;
        while (i < left.size() && j < right.size()) {
            list.set(k++, cmp.compare(left.get(i), right.get(j)) <= 0 ? left.get(i++) : right.get(j++));
        }
        while (i < left.size()) list.set(k++, left.get(i++));
        while (j < right.size()) list.set(k++, right.get(j++));
    }
}

unitTests:
Random rnd = new Random(42);
int[] big = new int[100_000];
for (int i = 0; i < big.length; i++) big[i] = rnd.nextInt(1_000_000);

test("insertion sort", () -> {
    int[] a = {5, 2, 4, 6, 1, 3};
    Sorts.insertionSort(a);
    checkEq(a, new int[] {1, 2, 3, 4, 5, 6});
    int[] e = {};
    Sorts.insertionSort(e);
    checkEq(e.length, 0);
});

test("merge sort", () -> {
    int[] a = {38, 27, 43, 3, 9, 82, 10, 3};
    checkEq(Sorts.mergeSort(a), new int[] {3, 3, 9, 10, 27, 38, 43, 82});
    checkEq(a[0], 38);
    int[] sorted = Sorts.mergeSort(big);
    boolean ok = true;
    for (int i = 1; i < sorted.length; i++) if (sorted[i - 1] > sorted[i]) ok = false;
    check(ok && sorted.length == big.length, "100 000 numbers should come out sorted");
});

test("counting inversions", () -> {
    checkEq(Sorts.countInversions(new int[] {2, 4, 1, 3, 5}), 3L);
    checkEq(Sorts.countInversions(new int[] {1, 2, 3}), 0L);
    checkEq(Sorts.countInversions(new int[] {3, 2, 1}), 3L);
    checkEq(Sorts.countInversions(new int[] {2, 2, 1}), 2L);
    int[] desc = new int[100_000];
    for (int i = 0; i < desc.length; i++) desc[i] = desc.length - i;
    checkEq(Sorts.countInversions(desc), 100_000L * 99_999 / 2);
});

test("stable sort of a list", () -> {
    record P(String name, int age) { }
    List<P> people = new ArrayList<>(List.of(new P("Cy", 30), new P("Ada", 36), new P("Bo", 30), new P("Di", 36), new P("Ed", 20)));
    Sorts.stableSort(people, Comparator.comparingInt(P::age));
    checkEq(people.stream().map(P::name).toList(), List.of("Ed", "Cy", "Bo", "Ada", "Di"));
});

